
from pathlib import Path
import argparse

import pandas as pd
from sklearn.ensemble import IsolationForest
from sklearn.impute import SimpleImputer
from sklearn.pipeline import Pipeline


# Use metrics already generated by the current QC engine.
FEATURES = [
    "Total_M_reads",
    "R1_N_%",
    "R2_N_%",
    "R1_Adapter_%",
    "R2_Adapter_%",
]


def detect_anomalies(input_file, output_file):
    """Flag unusual samples without changing existing QC decisions."""

    input_file = Path(input_file)
    output_file = Path(output_file)

    df = pd.read_csv(input_file, sep="\t")

    missing = [
        column for column in FEATURES
        if column not in df.columns
    ]
    if missing:
        raise ValueError(f"Missing required columns: {missing}")

    if "Sample" not in df.columns:
        raise ValueError("Input must contain a Sample column.")

    # Convert metric columns to numeric; invalid values become missing.
    X = df[FEATURES].apply(pd.to_numeric, errors="coerce")

    # Exclude samples with no usable metrics.
    usable = X.notna().any(axis=1)
    df = df.loc[usable].copy()
    X = X.loc[usable].copy()

    # Isolation Forest needs multiple samples to compare.
    if len(df) < 5:
        raise ValueError(
            f"Only {len(df)} usable samples found. "
            "At least 5 are required for this demonstration; "
            "10+ representative samples are preferable."
        )

    # Exclude metrics that are entirely missing or constant.
    X = X.dropna(axis=1, how="all")
    X = X.loc[:, X.nunique(dropna=True) > 1]

    if X.empty:
        raise ValueError(
            "No variable QC metrics available for anomaly detection."
        )

    # Fill occasional missing values using each metric's median.
    model = Pipeline([
        ("imputer", SimpleImputer(strategy="median")),
        ("detector", IsolationForest(
            n_estimators=200,
            contamination=0.10,
            random_state=42,
        )),
    ])

    predictions = model.fit_predict(X)

# Higher scores indicate more unusual samples.
    anomaly_scores = -model.decision_function(X)


    df["ML_anomaly_score"] = anomaly_scores.round(4)
    df["ML_anomaly"] = predictions == -1
    df["ML_assessment"] = df["ML_anomaly"].map({
        True: "REVIEW",
        False: "NO_ANOMALY_FLAG",
    })

    def explain_anomaly(row):
        if not row["ML_anomaly"]:
            return "No anomaly detected by the model."

        reasons = []

        if row["Total_M_reads"] < 10:
            reasons.append("low read count")

        if row["R1_N_%"] > 1:
            reasons.append("high R1 N-content")

        if row["R2_N_%"] > 1:
            reasons.append("high R2 N-content")

        if row["R1_Adapter_%"] > 5:
            reasons.append("high R1 adapter content")

        if row["R2_Adapter_%"] > 5:
            reasons.append("high R2 adapter content")

        if reasons:
            return (
                "Review unusual sample; observed: "
                + ", ".join(reasons)
                + "."
            )

        return (
            "Model flagged this sample, but the configured "
            "explanation checks found no listed metric above "
            "its threshold. Investigate its metric combination "
            "and compare with similar samples."
        )

    df["ML_explanation"] = df.apply(explain_anomaly, axis=1)



    # Keep the original QC status and flags unchanged.
    output_file.parent.mkdir(parents=True, exist_ok=True)
    df.to_csv(output_file, sep="\t", index=False)

    print(f"Samples analysed: {len(df)}")
    print(f"Metrics used: {', '.join(X.columns)}")
    print(f"Samples flagged for review: {df['ML_anomaly'].sum()}")
    print(f"Output written to: {output_file}")

    return df


def make_demo_data():
    """Create illustrative data for testing; not real sequencing data."""

    rows = []

    for i in range(1, 13):
        rows.append({
            "Sample": f"DEMO{i:02d}",
            "Total_M_reads": 20 + (i % 4),
            "R1_N_%": 0.1 + (i % 3) * 0.05,
            "R2_N_%": 0.1 + (i % 2) * 0.05,
            "R1_Adapter_%": 0.5 + (i % 3) * 0.1,
            "R2_Adapter_%": 0.6 + (i % 2) * 0.1,
            "QC_status": "PASS",
            "QC_flags": "",
        })

    # Inject an obvious artificial outlier for testing.
    rows[-1]["Total_M_reads"] = 2
    rows[-1]["R1_N_%"] = 8.0
    rows[-1]["R2_Adapter_%"] = 30.0

    return pd.DataFrame(rows)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--input",
        default="results/sample_qc.tsv",
        help="Existing sample QC TSV",
    )
    parser.add_argument(
        "--output",
        default="results/qc_anomalies.tsv",
        help="Anomaly results TSV",
    )
    parser.add_argument(
        "--demo",
        action="store_true",
        help="Test with artificial data instead of real QC results",
    )
    args = parser.parse_args()

    if args.demo:
        demo_file = Path("results/demo_sample_qc.tsv")
        demo_file.parent.mkdir(parents=True, exist_ok=True)
        make_demo_data().to_csv(demo_file, sep="\t", index=False)
        input_file = demo_file
    else:
        input_file = args.input

    detect_anomalies(input_file, args.output)


if __name__ == "__main__":
    main()
